#include "quickjs.h"
#include <stdio.h>
#include <string.h>
int main(void){JSRuntime*r=JS_NewRuntime();JSContext*c=JS_NewContext(r);const char*s="function Good(x,y){this.x=x;this.y=y;}function Bad(x,y){this.x=x+1;this.y=y;}function point(c){return new c(7,8);}for(var i=0;i<80;i++){point(Good);point(Bad);}point(Good).x;";JSValue fn=JS_Eval(c,s,strlen(s),"prepared-negative.js",JS_EVAL_TYPE_GLOBAL|JS_EVAL_FLAG_COMPILE_ONLY);JSValue v=JS_EvalFunction(c,JS_DupValue(c,fn));if(JS_IsException(v))return 2;JS_FreeValue(c,v);JS_RunGC(r);size_t n;uint8_t*data=JS_WriteObject(c,&n,fn,JS_WRITE_OBJ_BYTECODE);if(!data)return 3;for(int rom=0;rom<2;rom++){JSValue f=JS_ReadObject(c,data,n,JS_READ_OBJ_BYTECODE|(rom?JS_READ_OBJ_ROM_DATA:0));if(JS_IsException(f))return 4;v=JS_EvalFunction(c,f);int32_t k;if(JS_IsException(v)||JS_ToInt32(c,&k,v)||k!=7)return 5;JS_FreeValue(c,v);JS_RunGC(r);}JS_FreeValue(c,fn);JS_FreeContext(c);js_free_rt(r,data);JS_RunGC(r);JS_FreeRuntime(r);puts("NEGATIVE_INDEX_NORMAL_ROM_SERIALIZATION_PASS");return 0;}
